  function schedulePlotRedraw(entries){if(entries?.length){entries.forEach(entry=>{const canvas=entry.target,width=Math.max(0,Math.round(entry.contentRect.width)),height=Math.max(0,Math.round(entry.contentRect.height)),previous=state.plot.observedSizes.get(canvas);if(!width||!height||(previous&&previous.width===width&&previous.height===height))return;state.plot.pendingCanvases.add(canvas);});}else document.querySelectorAll('#geometryCanvas,#bodyPlanCanvas,#buttockCanvas,#curveCanvas,#individualCurveCanvas').forEach(canvas=>state.plot.pendingCanvases.add(canvas));if(!state.plot.pendingCanvases.size||state.plot.resizeFrame)return;state.plot.resizeFrame=requestAnimationFrame(()=>{state.plot.resizeFrame=null;const dirty=state.plot.pendingCanvases;state.plot.pendingCanvases=new Set();if(state.activeTab==='geometry'){if(dirty.has($('geometryCanvas')))drawGeometry();if(dirty.has($('bodyPlanCanvas')))drawBodyPlan();if(dirty.has($('buttockCanvas')))drawButtockPlan();}else if(state.activeTab==='curves'){if(dirty.has($('curveCanvas')))drawCurve();if(dirty.has($('individualCurveCanvas')))redrawIndividualCurves();}});}
