tener('click',toggleTheme);$('viewMode').addEventListener('change',e=>{state.viewMode=e.target.value;renderViewerOptions();drawBodyPlan();});['showGrid','showAxes','showKeel','showChine','showSheer','showStations','showWaterlines','showLongitudinals','showOffsets','showWaterplane'].forEach(id=>$(id).addEventListener('change',renderViewerOptions));['stationDensity','waterlineDensity','longitudinalDensity','visualScale','projectionMode'].forEach(id=>$(id).addEventListener('input',renderViewerOptions));['sternClosure','bowClosure','bottomClosure'].forEach(id=>$(id).addEventListener('change',()=>{if(!state.rows.length)return;ensureRenderGeometry(true);drawAllGeometry();}));$('renderResolution').addEventListener('change',e=>{state.renderResolution=e.target.value;ensureRenderGeometry(true);drawAllGeometry();});$('renderFairing').addEventListener('change',()=>{if(!state.rows.length)return;ensureRenderGeometry(true);drawAllGeometry();});$('fitHull').addEventListener('click',()=>state.viewer?.fit());document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>set3DView(b.dataset.view)));$('waterlineSelectors').addEventListener('click',e=>{const b=e.target.closest('[data-waterline]');if(!b)return;state.selectedWaterline=Number(b.dataset.waterline);updateStationSelector();ensureRenderGeometry(true);drawAllGeometry();});$('stationSelectors').addEventListener('click',e=>{const b=e.target.closest('[data-station]');if(!b)return;state.selectedStation=Number(b.dataset.station);updateStationSelector();ensureRenderGeometry(true);drawAllGeometry();});$('maxsurfTolerance').addEventListener('change',renderMaxsurfComparison);$('maxsurfComparison').addEventListener('change',e=>{const draftKey=e.target.dataset.maxsurfDraft,conditionKey=e.target.dataset.maxsurfCondition,property=e.target.dataset.maxsurfProperty;if(draftKey){const condition=state.maxsurf.conditions.find(item=>item.key===draftKey),draft=Number(e.target.value);if(condition&&Number.isFinite(draft)&&draft>=0)condition.draft=Math.min(draft,state.geometry.maxSupportedDraft);}if(conditionKey&&property){const condition=state.maxsurf.conditions.find(item=>item.key===conditionKey),value=String(e.target.value).trim();if(condition){if(value==='')delete condition.values[property];else if(Number.isFinite(Number(value)))condition.values[property]=Number(value);}}renderMaxsurfComparison();});$('maxsurfCsvInput').addEventListener('change',e=>{if(e.target.files[0])importMaxsurfCsv(e.target.files[0]);});$('exportMaxsurfCsv').addEventListener('click',exportMaxsurfCsv);$('exportMaxsurfXlsx').addEventListener('click',exportMaxsurfXlsx);document.querySelectorAll('.tab-button').forEach(b=>b.addEventListener('click',()=>activateTab(b.dataset.tab)));document.querySelectorAll('[data-open-tab]').forEach(b=>b.addEventListener('click',()=>activateTab(b.dataset.openTab)));
